import java.io.IOException;
import java.io.InputStream;
import java.lang.annotation.Annotation;
import java.lang.reflect.Type;

import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.MultivaluedMap;
import javax.ws.rs.ext.MessageBodyReader;
import javax.ws.rs.ext.MessageBodyWriter;

import org.apache.abdera.Abdera;
import org.apache.abdera.model.Document;
import org.apache.abdera.model.Element;
import org.apache.abdera.parser.Parser;
import org.apache.abdera.parser.ParserOptions;

/**
 * A thread‑safe, XXE‑protected Atom provider.
 */
public abstract class AbstractAtomProvider<T extends Element>
        implements MessageBodyWriter<T>, MessageBodyReader<T> {

    /** Shared Abdera engine – immutable after construction. */
    private static final Abdera ATOM_ENGINE = new Abdera();

    /** Whether to autodetect charset from the XML payload. */
    private boolean autodetectCharset;

    /* --------------------------------------------------------------------- */
    /* MessageBodyReader implementation                                       */
    /* --------------------------------------------------------------------- */

    @Override
    public T readFrom(Class<T> clazz, Type t, Annotation[] a, MediaType mt,
                      MultivaluedMap<String, String> headers, InputStream is)
            throws IOException {

        /*
         * Create a fresh ParserOptions instance for each request.  This guarantees
         * that the entity‑resolution flag is set before parsing and that no
         * concurrent thread can modify the same options object.
         *
         * The options are passed directly to the parse() call, so the global
         * parser configuration remains untouched and reusable across threads.
         */
        ParserOptions options = new ParserOptions();
        options.setAutodetectCharset(autodetectCharset);
        options.setResolveEntities(false);   // Disable external entity resolution

        Parser parser = ATOM_ENGINE.getParser();

        /*
         * The Abdera Parser provides an overload that accepts ParserOptions.
         * Passing the options explicitly ensures that the parser behaves
         * deterministically for this invocation, even when the underlying
         * parser instance is shared.
         */
        Document<T> doc = parser.parse(is, options);

        if (doc == null || doc.getRoot() == null) {
            throw new IOException("Failed to parse Atom document");
        }

        return doc.getRoot();
    }

    /* --------------------------------------------------------------------- */
    /* Other methods omitted for brevity                                      */
    /* --------------------------------------------------------------------- */
}
