import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a unique file inside {@code dir} using {@code name}.  
     * The method protects against directory‑traversal attacks by ensuring that
     * the resolved path stays within {@code dir}.  Query parameters are stripped
     * from {@code name} as before.
     *
     * @param dir  the base directory where the file should be created
     * @param name the requested file name (may contain a query string)
     * @return a {@link File} object pointing to a non‑existing file inside {@code dir}
     * @throws IllegalArgumentException if the resolved path escapes {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null || name == null) {
            throw new NullPointerException("Directory and name must not be null");
        }

        // Strip query parameters
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Resolve the target path and normalize it
        Path dirPath = dir.toPath().toAbsolutePath().normalize();
        Path targetPath = dirPath.resolve(name).normalize();

        // Ensure the target is still under the intended directory
        if (!targetPath.startsWith(dirPath)) {
            throw new IllegalArgumentException(
                "Attempt to create a file outside the target directory: " + name);
        }

        File file = targetPath.toFile();

        // Handle duplicate names by appending "-n" before the extension
        int dot = name.indexOf('.');
        String prefix = dot < 0 ? name : name.substring(0, dot);
        String suffix = dot < 0 ? "" : name.substring(dot);
        int index = 2;
        while (file.exists()) {
            file = new File(dir, prefix + "-" + index++ + suffix);
        }

        // Create any missing parent directories
        File parent = file.getParentFile();
        if (parent != null && !parent.exists()) {
            parent.mkdirs();
        }

        return file;
    }

    // other methods
}
