     * Safely expands archive entries into the specified target directory.
     *
     * @param supplier      provides the next readable entry
     * @param writer        writes entry data to an output stream
     * @param targetDirectory the root directory where files will be extracted
     * @throws IOException if a path‑traversal attempt is detected or I/O fails
     */
    private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
        // Resolve the canonical path of the target directory once
        Path canonicalTargetPath = targetDirectory.getCanonicalFile().toPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            String entryName = nextEntry.getName();

            // Basic sanity checks – reject absolute paths and any component that could
            // lead to a traversal outside the target directory.
            if (entryName == null || entryName.isEmpty()
                    || entryName.contains("..")
                    || entryName.startsWith("/")
                    || entryName.startsWith("\\")
                    || entryName.matches("^[a-zA-Z]:.*")) {
                throw new IOException("Invalid entry name: " + entryName);
            }

            // Normalize the entry path to collapse any redundant separators or "." components
            Path entryPath = Paths.get(entryName).normalize();

            // Resolve the full path within the target directory
            Path resolvedPath = canonicalTargetPath.resolve(entryPath).normalize();

            // Ensure the resolved path is still under the target directory
            if (!resolvedPath.startsWith(canonicalTargetPath)) {
                throw new IOException("Entry '" + entryName + "' would create a file outside of "
                        + targetDirectory.getAbsolutePath());
            }

            File f = resolvedPath.toFile();

            if (nextEntry.isDirectory()) {
                if (!f.isDirectory() && !f.mkdirs()) {
                    throw new IOException("Failed to create directory " + f);
                }
            } else {
                // Ensure parent directories exist
                File parent = f.getParentFile();
                if (parent != null && !parent.isDirectory() && !parent.mkdirs()) {
                    throw new IOException("Failed to create directory " + parent);
                }

                try (OutputStream o = Files.newOutputStream(f.toPath())) {
                    writer.writeEntryDataTo(nextEntry, o);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

    // other methods

}
